contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);

        bool reverted;
        bool success;
        bytes memory data = abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[0], v);
        (bool ok0,) = caddress.call(data);
        for (uint i = 1; i < _tos.length; i++) {
            (bool oki,) = caddress.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, _tos[i], v));
            ok0 = ok0 && oki;
        }

        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            success = r;
            reverted = false;
        } catch {
            success = false;
            reverted = true;
        }

        assert(reverted == !ok0);
    }

    receive() external payable {}
}

